import sys


def read_matrix(data):
    n = int(data[0])
    vals = [int(t) for t in data[1:1 + n * n]]
    return n, [vals[i * n:(i + 1) * n] for i in range(n)]


def positivity(n, d):
    """Returns the first (i, j) breaking it, in index order, or None."""
    for i in range(n):
        for j in range(n):
            if d[i][j] < 0:
                return (i, j)
            if (d[i][j] == 0) != (i == j):
                return (i, j)
    return None


def symmetry(n, d):
    for i in range(n):
        for j in range(n):
            if d[i][j] != d[j][i]:
                return (i, j)
    return None


def triangle(n, d):
    """The first (i, j, k) with d[i][k] > d[i][j] + d[j][k]."""
    for i in range(n):
        for j in range(n):
            for k in range(n):
                if d[i][k] > d[i][j] + d[j][k]:
                    return (i, j, k)
    return None


def main():
    data = sys.stdin.read().split()
    if not data:
        return
    n, d = read_matrix(data)

    p = positivity(n, d)
    s = symmetry(n, d)
    t = triangle(n, d)

    print("positivity ok" if p is None else "positivity fails at %d %d" % p)
    print("symmetry ok" if s is None else "symmetry fails at %d %d" % s)
    print("triangle ok" if t is None else "triangle fails at %d %d %d" % t)
    print("metric", "yes" if p is None and s is None and t is None else "no")


main()
